import{_ as o}from"./chunks/settings-sw.pc.en.BBIXvrM0.js";import{_ as t,o as a,c as r,a5 as s}from"./chunks/framework.BYXPg_yw.js";const f=JSON.parse('{"title":"Update","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/gui/software-update.md","filePath":"manual/gui/software-update.md","lastUpdated":1793350928000}'),d={name:"manual/gui/software-update.md"};function n(i,e,h,c,l,p){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="update" tabindex="-1">Update <a class="header-anchor" href="#update" aria-label="Permalink to &quot;Update&quot;">​</a></h1><p>Open the <code>Update</code> tile on the hub, or <code>Update</code> in the logo menu. The screen has two tabs: <code>Software update</code> updates the software running on the robot and this app itself, and <code>Firmware update</code> updates the boards inside the robot (see <a href="#board-firmware">Firmware update</a>). The tile opens without a robot connected and is locked while <a href="/RBQ/nightly/manual/gui/emergency.html#spectating">spectating</a>. A dot on the tile means a robot package that <code>Auto update</code> downloaded is waiting to be installed, or a board needs a firmware update.</p><p><img src="'+o+'" alt="Software update section"></p><h2 id="robot-software" tabindex="-1">Robot software <a class="header-anchor" href="#robot-software" aria-label="Permalink to &quot;Robot software&quot;">​</a></h2><p>The top of the panel shows two cards:</p><ul><li><code>Current robot</code> · Motion — <code>Version</code>, <code>Branch</code>, <code>Commit</code>, <code>Build</code> as reported by the robot.</li><li><code>Update file</code> — the package you are about to send: <code>Selected</code> file name, its <code>Version</code>, <code>Size</code>, the <code>Target</code>, and the target PC&#39;s <code>System</code> — its Ubuntu version and processor, for example <code>u24-x86_64</code>. <code>—</code> means this device has not connected to that robot yet. <code>Older (RBQ-*)</code> means the robot runs older robot software that does not report its <code>System</code>.</li></ul><h3 id="choosing-a-package" tabindex="-1">Choosing a package <a class="header-anchor" href="#choosing-a-package" aria-label="Permalink to &quot;Choosing a package&quot;">​</a></h3><p>There are two ways to get a package onto the device.</p><p><strong>Online</strong> — the list below the cards shows the versions published for this app&#39;s release channel (<code>Online update</code> · <code>internet required</code>). Press <code>Check versions</code> (or <code>Refresh</code>) to fetch the list, then <code>Download</code> on the version you want. The download pulls the robot package onto this device, along with the app build on the Linux desktop app. The row then shows the package size, plus <code>Latest</code> and <code>In use</code> badges where they apply. Each robot package is built for one <code>System</code>. The app learns each robot&#39;s <code>System</code> every time it connects to that robot, and remembers it for that robot after the app or device restarts. The download is for the robot currently selected on the hub, so you can download on the internet network and switch to the robot network before sending. If this device has never connected to that robot, the app downloads the package for every <code>System</code>, about four times the size, and sends the one that matches the robot. A robot showing <code>Older (RBQ-*)</code> gets the older <code>RBQ-*</code> packages instead. The robot also refuses a version older than the one it is running. <code>Remove</code> deletes a downloaded package. The <code>Release notes</code> under the list cover the selected version, or the version the robot is running when nothing is selected. If a download stops, press <code>Download</code> again — it continues from where it stopped.</p><p><strong>From USB or a file</strong> — press <code>Load from USB or file</code>. The system file picker opens (a USB OTG drive shows up there like any other storage). On a Steam Deck in Gaming Mode the app opens its own <code>Choose a file</code> window instead, with shortcuts to <code>Home</code>, <code>Download</code>, <code>Music</code>, <code>Documents</code> and <code>Desktop</code>, any inserted SD card or USB drive, and <code>Up</code> to move to the parent folder. Pick the package file. It must be the package for that robot&#39;s <code>System</code>, named <code>core-&lt;version&gt;-&lt;system&gt;.rbq</code>. Robots on older robot software that show no <code>System</code> take <code>RBQ-&lt;version&gt;.zip</code> or <code>RBQ-&lt;version&gt;.tar.gz</code> instead. The <code>Update file</code> card fills in with the file&#39;s name, version, and size.</p><h3 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h3><p><code>Target</code> selects which robot PC receives the package: <code>Motion</code> (the robot IP you are connected to) or <code>Vision</code>. Vision matters only on older robots that have a separate vision PC. If the robot has no vision IP set — the <code>Vision IP</code> field in its profile on the hub, or <code>Vision PC IP (optional)</code> when you add it by address, both <a href="/RBQ/nightly/manual/gui/developer-mode.html">developer mode</a> — the app falls back to the default vision address and says so in a note.</p><h3 id="sending" tabindex="-1">Sending <a class="header-anchor" href="#sending" aria-label="Permalink to &quot;Sending&quot;">​</a></h3><ol><li>Press <code>Send robot software</code>.</li><li>The dialog <code>Send to the robot?</code> lists the file, size, and target. If the file is a robot package, the dialog warns that the robot will unpack and deploy it as soon as the transfer completes, replacing the running software. The dialog says files with any other name are only stored on the robot, but current robot software refuses them outright with a &quot;Rejected file name&quot; error — send only properly named packages. If the package is for a different <code>System</code> than the robot, or the robot no longer accepts <code>RBQ-*</code> packages, the app does not send it and tells you to download again with the robot connected.</li><li>Press <code>Send</code>. The progress bar shows the percentage, and <code>Cancel</code> aborts the transfer. If the connection drops — the network blips, or you leave the app and come back — the card shows <code>Reconnecting</code> and the app sends the rest from where the robot stopped. Once the whole file is on the robot the card shows <code>Installing on robot</code> while the robot unpacks and installs it. <code>Cancel</code> is gone at this stage: the robot finishes the install even if the connection drops, and the app reconnects to read the result. If the install fails, the robot puts the previous version back and the app shows why.</li><li>On success the panel shows <code>✓ Transfer complete</code> and asks <code>Deploy transfer complete — reboot now?</code>. With a <code>Vision</code> target the dialog only says the vision PC cannot be rebooted from the app and closes with <code>Check</code>.</li></ol><h3 id="reboot" tabindex="-1">Reboot <a class="header-anchor" href="#reboot" aria-label="Permalink to &quot;Reboot&quot;">​</a></h3><p>Robot software takes effect only after you restart the robot service or reboot the robot PC. For a <code>Motion</code> target the reboot prompt offers <code>Restart robot service</code> and <code>Reboot robot PC</code>, with <code>Later</code> below them. <code>Restart robot service</code> restarts only the robot software and leaves the PC running, which is enough to apply the update; a robot set up without that service shows <code>Restart request failed</code>, and then use <code>Reboot robot PC</code>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Rebooting cuts motor power and the robot will sag to the ground. The robot must be in the <strong>sitting</strong> state before you reboot — sit it down first and make sure it is resting on the floor, and do not move it during the reboot. If the robot is standing, <code>Restart robot service</code> is refused with <code>Restart request failed</code>, while <code>Reboot robot PC</code> is ignored without an error. The app connection drops while the robot restarts. Reconnect afterwards and check that <code>Current robot</code> shows the new version.</p></div><p>The vision PC cannot be rebooted from the app. If the target was <code>Vision</code>, reboot that PC by hand.</p><h2 id="this-app" tabindex="-1">This app <a class="header-anchor" href="#this-app" aria-label="Permalink to &quot;This app&quot;">​</a></h2><p>The <strong>GUI Version</strong> line shows the version of the app you are running, followed by a badge:</p><ul><li>no badge — a release build,</li><li><code>NIGHTLY</code> — a nightly build (its list shows <code>Nightly builds</code> · <code>last 10 kept</code> instead of the release list),</li><li><code>LOCAL</code> — a local build with no release channel; it does not check for updates.</li></ul><p>Next to it, <code>Matches robot</code> (with a check mark) or <code>Differs from robot</code> compares the app version with the robot version. Keeping the two the same is the intended pairing.</p><p>Once the version list has loaded, an update button appears if a newer app is available:</p><ul><li><code>Update in store</code> — store installs (Google Play / App Store). The store app opens; install from there.</li><li><code>&lt;version&gt; Update</code> — APK and desktop installs. The app downloads the build and installs it: Android hands it to the system installer, the Linux desktop app switches to the new build, and the Windows app runs the installer — <strong>the app closes right away and reopens on the new version</strong>, so any robot connection drops. On Windows the app first asks for confirmation (<code>App update</code>), and refuses with <code>The robot is standing — updating closes the app and drops the connection. Sit the robot down, then try again</code> while a connected robot is standing. Before running the installer it checks the download against the published checksum and stops if they differ. <code>You&#39;re on the latest version</code> is shown when nothing newer exists.</li></ul><p>On the Linux desktop app, <code>Install online</code> registers a build you downloaded but never installed, and <code>Use this build</code> switches to any downloaded build in the list.</p><p>Nightly builds only see nightly releases and release builds only see releases — the channel is fixed when the app is built.</p><h2 id="board-firmware" tabindex="-1">Firmware update <a class="header-anchor" href="#board-firmware" aria-label="Permalink to &quot;Firmware update {#board-firmware}&quot;">​</a></h2><p><code>Firmware update</code> updates the boards inside the robot (16 leg motors, PDU, IF, SIDE_F, SIDE_H and TOP) to the latest firmware files stored on the robot. It is a different tab from <code>Software update</code>, which replaces the software on the robot PC. The robot reads each board&#39;s hw and picks the file for it. If the robot has no firmware file named with its hw for a kind of board, those boards are marked <code>Not managed</code> and skipped.</p><p>The 16 leg motors must all run the same firmware, so they are treated as one group. In the counts and lists on this screen the motors are one item (<code>Motors (n)</code>). A motor whose version matches but whose contents differ from the file is written again, and a banner appears at the top when the motors run different firmware. If any motor cannot be updated (for example a downgrade you did not agree to), the robot writes none of the motors and tells you why.</p><table tabindex="0"><thead><tr><th>Row</th><th>Effect</th></tr></thead><tbody><tr><td><code>Status</code></td><td>Counts the boards as <code>Updatable</code>, <code>Latest</code> and <code>Needs check</code>. The motor group counts as one. Boards that do not answer are counted as <code>no response</code>, and skipped boards as <code>Not managed</code>. <code>Check versions</code> makes the robot read the version and hw of every board again. It cannot be pressed while the robot is standing or walking.</td></tr><tr><td><code>Update all</code></td><td>Updates the boards that need it one at a time, in the order PDU → IF → SIDE_F → SIDE_H → TOP → leg motors. It opens a confirmation first.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Update all cuts leg and arm power first, and leg and arm power stay off when it finishes. Start the robot again afterwards. Leg power is turned on only while the leg motors are updated. UPC power goes off briefly while the PDU is updated, and the 12V ports while the TOP board is updated. An update can start only while the robot is sitting or its control is off, and only while it is sitting if the joints are under control. It can also start after an emergency stop as long as leg power is off (a TOP board without an hw record holds the emergency stop).</p></div><p>When <code>Update all</code> cannot be pressed, the reason appears under the row.</p><ul><li><code>The robot is active — sit it down and try again</code> — the robot is standing or walking. It also appears when the joints are under control but the robot is not sitting, such as during auto start.</li><li><code>Another device has control</code> — another device holds control of the robot.</li><li><code>Some boards need checking</code> — the robot has no file for a board, or does not know the board&#39;s hw and so cannot pick a file. The board name and the reason follow. While any such board exists, the whole update does not run.</li><li><code>No boards to update</code> — every board is up to date or <code>Not managed</code>.</li><li><code>The robot is busy with firmware work — try again when it has finished</code> — the robot is doing other firmware work.</li><li><code>The robot software does not support this — run Software update first</code></li></ul><p>A board left in boot does not block the update even if its hw is unknown. The robot sends that board to its app, reads the hw again and then updates it with the matching file. The update is not blocked either when leg power is off and no motor answers. The robot then turns leg power on during the update and checks the motors.</p><p>One confirmation dialog lists the boards and everything you agree to. If the legs or the arm are under control, a sentence says power will be cut first, and the button becomes <code>Cut power and update</code>. If a board would go down to an older version than the one it has, that board and both versions are named (the motors in one sentence), and a board that was running firmware for another variant gets a sentence saying it is switched to the matching variant. If the check ran with leg power off, the motors have no verdict and you cannot agree to a motor downgrade. To take the motors down, press <code>Check versions</code> again with leg power on. If the robot&#39;s check result changes after the dialog opened, the update is not sent and the dialog asks again with the changes.</p><p>While the update runs, the same place shows the steps (<code>48V off</code>, the board names, <code>Legs on</code>, <code>Motor</code>, <code>Legs off</code>). The board being written gets a progress bar, and a resend shows its count, such as <code>Retry 1/3</code>. There is no stop button, and the update keeps running on the robot even if you close the screen. At the end you see <code>Update complete — n boards</code> with a note that power is still off. If it fails, the reason appears and the robot stops with leg power off. When sending to a board fails, the robot tries again up to three more times after the first attempt. If those fail too, it leaves that board in boot and stops. Update again after a moment.</p><p>A motor boot replacement started from the research screen also shows here, as <code>Boot replace</code> with the motor name, and its steps read <code>Checking updater</code>, <code>Sending boot</code>, <code>Writing boot</code> and <code>Confirming new boot</code>. Leave power on while it runs.</p><p>Motor firmware 261028 or later is not written to a motor whose bootloader is older than BOOT0 261027, or whose bootloader version the robot could not read. That firmware starts the data phase at 3M when its EEPROM is blank, while an older bootloader talks only at 4M, so the next update would lose the board. The update then stops with a reason such as <code>HRP was not updated: its bootloader is too old for this firmware (261028 or later), and the next update would lose the board. Replace the bootloader first on the Research screen (BOOT0 261027 or later), then update again.</code> Replace the bootloader first, then update again.</p><h3 id="board-firmware-banner" tabindex="-1">Top banners <a class="header-anchor" href="#board-firmware-banner" aria-label="Permalink to &quot;Top banners {#board-firmware-banner}&quot;">​</a></h3><p>These banners can appear at the top of the hub and other screens.</p><ul><li><code>Some boards need a firmware update (IF)</code> — a board was left in boot, or a board is on standby because its firmware does not support its hw. <code>Open</code> brings you to this section.</li><li><code>Motor firmware is mixed — run a firmware update</code> — the motors differ in firmware version or verdict. <code>Open</code> brings you to this section.</li><li><code>Some boards need an hw record — contact an administrator</code> — a board is on standby because no hw is recorded on it. An update does not clear this.</li><li><code>A board is on standby because its EEPROM does not respond — contact an administrator</code> — the board cannot read its hw and is on standby. An update does not clear this.</li></ul><p>The X on the right of a banner closes it. It comes back when a different board is affected or when you reconnect to the robot.</p><blockquote><p><strong>What developer mode adds here</strong> is collected on <a href="/RBQ/nightly/manual/gui/developer-mode.html#board-firmware">Developer mode</a>.</p></blockquote>',43)])])}const w=t(d,[["render",n]]);export{f as __pageData,w as default};
